import itertools

def is_costas(perm):
    n = len(perm)
    vectors = set()
    for c1 in range(n):
        for c2 in range(c1+1, n):
            dc = c2 - c1
            dr = perm[c2] - perm[c1]
            vec = (dr, dc)
            if vec in vectors:
                return False
            vectors.add(vec)
    return True

found = False
for p in itertools.permutations(range(9)):
    if is_costas(p):
        print(p)
        found = True
        break

print("Found:", found)
